import { test, expect } from '@playwright/test';

test.describe('Filter Tags Removal', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should remove a single filter tag by clicking the x icon', async ({ page }) => {
    // Add a filter tag first
    const filterInput = page.getByRole('textbox', { name: /filter/i });
    await filterInput.fill('category:electronics');
    await page.keyboard.press('Enter');

    // Verify the filter tag is displayed
    const filterTag = page.getByText('category:electronics');
    await expect(filterTag).toBeVisible();

    // Click the x icon to remove the filter tag
    const removeButton = page.getByRole('button', { name: /remove.*category:electronics/i });
    await removeButton.click();

    // Verify the filter tag is removed
    await expect(filterTag).not.toBeVisible();
  });

  test('should remove multiple filter tags individually', async ({ page }) => {
    // Add multiple filter tags
    const filterInput = page.getByRole('textbox', { name: /filter/i });

    await filterInput.fill('category:electronics');
    await page.keyboard.press('Enter');

    await filterInput.fill('price:high');
    await page.keyboard.press('Enter');

    await filterInput.fill('brand:sony');
    await page.keyboard.press('Enter');

    // Verify all filter tags are displayed
    await expect(page.getByText('category:electronics')).toBeVisible();
    await expect(page.getByText('price:high')).toBeVisible();
    await expect(page.getByText('brand:sony')).toBeVisible();

    // Remove the middle filter tag
    const removeButton = page.getByRole('button', { name: /remove.*price:high/i });
    await removeButton.click();

    // Verify only the middle tag is removed
    await expect(page.getByText('category:electronics')).toBeVisible();
    await expect(page.getByText('price:high')).not.toBeVisible();
    await expect(page.getByText('brand:sony')).toBeVisible();

    // Remove the first filter tag
    const removeFirstButton = page.getByRole('button', { name: /remove.*category:electronics/i });
    await removeFirstButton.click();

    // Verify the first tag is removed
    await expect(page.getByText('category:electronics')).not.toBeVisible();
    await expect(page.getByText('brand:sony')).toBeVisible();
  });

  test('should update search results when a filter tag is removed', async ({ page }) => {
    // Add a filter tag
    const filterInput = page.getByRole('textbox', { name: /filter/i });
    await filterInput.fill('category:electronics');
    await page.keyboard.press('Enter');

    // Verify results are filtered
    const resultCount = page.getByText(/showing \d+ results/i);
    const initialCount = await resultCount.textContent();

    // Remove the filter tag
    const removeButton = page.getByRole('button', { name: /remove.*category:electronics/i });
    await removeButton.click();

    // Verify results are updated
    const updatedCount = await resultCount.textContent();
    expect(initialCount).not.toEqual(updatedCount);
  });
});
